# Sharded Concurrent Map in Rust

The core idea: split the map into N independent shards, each guarded by its own `RwLock`. A key's hash decides which shard owns it, so threads working on different shards never block each other. `RwLock` is preferred over `Mutex` because read-heavy workloads benefit from concurrent readers.

```rust
use std::collections::HashMap;
use std::hash::{BuildHasher, Hash, Hasher};
use std::sync::RwLock;
use std::collections::hash_map::RandomState;

/// A thread-safe concurrent map using lock sharding.
///
/// The map is partitioned into `N` shards. Each shard owns an
/// independent `RwLock<HashMap>`, so operations on keys that fall
/// into different shards proceed in parallel.
pub struct ShardedMap<K, V, S = RandomState> {
    shards: Box<[RwLock<HashMap<K, V, S>>]>,
    hash_builder: S,
    shard_mask: usize, // shard count is a power of two; mask = count - 1
}

impl<K, V> ShardedMap<K, V, RandomState>
where
    K: Hash + Eq,
{
    /// Create a map with a default shard count (16).
    pub fn new() -> Self {
        Self::with_shards(16)
    }

    /// Create a map with a specific shard count.
    /// Rounded up to the next power of two for fast modulo via masking.
    pub fn with_shards(shard_count: usize) -> Self {
        Self::with_shards_and_hasher(shard_count, RandomState::new())
    }
}

impl<K, V, S> ShardedMap<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher + Clone,
{
    pub fn with_shards_and_hasher(shard_count: usize, hash_builder: S) -> Self {
        let count = shard_count.max(1).next_power_of_two();
        let shards = (0..count)
            .map(|_| RwLock::new(HashMap::with_hasher(hash_builder.clone())))
            .collect::<Vec<_>>()
            .into_boxed_slice();

        Self {
            shards,
            hash_builder,
            shard_mask: count - 1,
        }
    }

    /// Determine which shard a key belongs to.
    fn shard_index<Q>(&self, key: &Q) -> usize
    where
        Q: Hash + ?Sized,
    {
        let mut hasher = self.hash_builder.build_hasher();
        key.hash(&mut hasher);
        (hasher.finish() as usize) & self.shard_mask
    }

    /// Insert a key/value pair. Returns the previous value if present.
    pub fn insert(&self, key: K, value: V) -> Option<V> {
        let idx = self.shard_index(&key);
        let mut shard = self.shards[idx].write().expect("shard poisoned");
        shard.insert(key, value)
    }

    /// Remove a key, returning its value if present.
    pub fn remove(&self, key: &K) -> Option<V> {
        let idx = self.shard_index(key);
        let mut shard = self.shards[idx].write().expect("shard poisoned");
        shard.remove(key)
    }

    /// Look up a key and clone the value out.
    /// Cloning lets us release the read lock immediately,
    /// avoiding lifetime entanglement with the guard.
    pub fn get(&self, key: &K) -> Option<V>
    where
        V: Clone,
    {
        let idx = self.shard_index(key);
        let shard = self.shards[idx].read().expect("shard poisoned");
        shard.get(key).cloned()
    }

    /// Run a closure with a reference to the value, holding the read lock
    /// only for the duration of the call. Useful when `V: !Clone` or
    /// when cloning is expensive.
    pub fn with<F, R>(&self, key: &K, f: F) -> Option<R>
    where
        F: FnOnce(&V) -> R,
    {
        let idx = self.shard_index(key);
        let shard = self.shards[idx].read().expect("shard poisoned");
        shard.get(key).map(f)
    }

    /// Run a closure with a mutable reference to the value, holding the
    /// write lock only for the duration of the call.
    pub fn with_mut<F, R>(&self, key: &K, f: F) -> Option<R>
    where
        F: FnOnce(&mut V) -> R,
    {
        let idx = self.shard_index(key);
        let mut shard = self.shards[idx].write().expect("shard poisoned");
        shard.get_mut(key).map(f)
    }

    /// True if the key is present.
    pub fn contains_key(&self, key: &K) -> bool {
        let idx = self.shard_index(key);
        let shard = self.shards[idx].read().expect("shard poisoned");
        shard.contains_key(key)
    }

    /// Total number of entries across all shards.
    /// Note: this is a snapshot. Concurrent writers may change the count
    /// between reading individual shards.
    pub fn len(&self) -> usize {
        self.shards
            .iter()
            .map(|s| s.read().expect("shard poisoned").len())
            .sum()
    }

    pub fn is_empty(&self) -> bool {
        self.shards
            .iter()
            .all(|s| s.read().expect("shard poisoned").is_empty())
    }

    /// Remove all entries.
    pub fn clear(&self) {
        for shard in self.shards.iter() {
            shard.write().expect("shard poisoned").clear();
        }
    }

    /// Number of shards. Useful for diagnostics and tuning.
    pub fn shard_count(&self) -> usize {
        self.shards.len()
    }
}

impl<K, V> Default for ShardedMap<K, V, RandomState>
where
    K: Hash + Eq,
{
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Arc;
    use std::thread;

    #[test]
    fn basic_ops() {
        let map: ShardedMap<String, i32> = ShardedMap::new();
        assert_eq!(map.insert("a".into(), 1), None);
        assert_eq!(map.insert("a".into(), 2), Some(1));
        assert_eq!(map.get(&"a".into()), Some(2));
        assert!(map.contains_key(&"a".into()));
        assert_eq!(map.remove(&"a".into()), Some(2));
        assert!(!map.contains_key(&"a".into()));
    }

    #[test]
    fn with_mut_updates_in_place() {
        let map: ShardedMap<&'static str, Vec<i32>> = ShardedMap::new();
        map.insert("nums", vec![1, 2, 3]);
        map.with_mut(&"nums", |v| v.push(4));
        assert_eq!(map.get(&"nums"), Some(vec![1, 2, 3, 4]));
    }

    #[test]
    fn concurrent_inserts() {
        let map = Arc::new(ShardedMap::<i32, i32>::with_shards(32));
        let mut handles = vec![];

        for t in 0..8 {
            let map = Arc::clone(&map);
            handles.push(thread::spawn(move || {
                for i in 0..1000 {
                    let key = t * 1000 + i;
                    map.insert(key, key * 2);
                }
            }));
        }
        for h in handles {
            h.join().unwrap();
        }

        assert_eq!(map.len(), 8 * 1000);
        assert_eq!(map.get(&4242), Some(8484));
    }

    #[test]
    fn shard_count_is_power_of_two() {
        let map: ShardedMap<i32, i32> = ShardedMap::with_shards(10);
        assert_eq!(map.shard_count(), 16);
    }
}
```

## Design notes

**Why power-of-two shard counts.** Using `hash & (count - 1)` is significantly faster than `hash % count`, and the rounding is invisible to callers.

**Why `RwLock` over `Mutex`.** Most maps see far more reads than writes. `RwLock` lets readers proceed concurrently within a shard. If your workload is write-heavy, swapping to `Mutex` is a one-line change and can actually be faster due to lower locking overhead.

**Why two read APIs (`get` and `with`).** `get` clones the value so the lock is released before returning, which is ergonomic but requires `V: Clone`. `with` accepts a closure and runs it under the read lock, which avoids cloning and works for any `V`. Keep the closure short to avoid blocking other writers on that shard.

**Lock poisoning.** I use `expect("shard poisoned")` to surface poisoning loudly. If you'd rather recover, replace with `.unwrap_or_else(|e| e.into_inner())`.

**What's missing on purpose.** No iteration API. A correct concurrent iterator either locks all shards (bad) or yields a snapshot (expensive). If you need it, expose `iter_shard(idx)` or a `snapshot()` that clones entries. For production use, consider [`dashmap`](https://crates.io/crates/dashmap), which implements this pattern with more features and finer-grained optimizations.

# Optimizing for High Read Contention

Under heavy read load, the original implementation has four hidden costs that don't show up in single-threaded benchmarks:

1. **`std::sync::RwLock` cache-line bouncing.** Even acquiring a read lock writes to the lock's internal reader counter. When many cores read the same shard, that counter ping-pongs between L1 caches.
2. **False sharing between shards.** Adjacent shards land on the same 64-byte cache line, so a writer on shard 5 invalidates the cache line holding shard 4's lock state for every other core.
3. **Deep value clones in `get`.** Returning `V: Clone` means each reader allocates its own copy. With many readers reading the same hot key, that's redundant work and memory pressure.
4. **Slow hasher and poisoning overhead.** `RandomState` (SipHash) is cryptographic and slow. `Result`-returning lock APIs add branches on every access.

## Changes

- Swap to `parking_lot::RwLock`: one-word size, no poisoning, faster uncontended path, and a writer-preferring fairness mode that avoids reader starvation of writers.
- Cache-line-pad each shard so locks live on independent cache lines.
- Store values as `Arc<V>`. Reads return an `Arc<V>` clone (a single atomic increment), so the shard lock is held only long enough to bump a refcount, not to deep-copy the value.
- Use `ahash` for faster, non-cryptographic hashing.
- Default shard count to `4 × available_parallelism()`, scaling with the machine.

## Updated implementation

```rust
use std::collections::HashMap;
use std::hash::{BuildHasher, Hash, Hasher};
use std::ops::Deref;
use std::sync::Arc;

use ahash::RandomState;
use parking_lot::RwLock;

/// Aligns its inner value to a 64-byte boundary so each shard's lock
/// occupies its own cache line. Eliminates false sharing across cores.
#[repr(align(64))]
struct CachePadded<T>(T);

impl<T> Deref for CachePadded<T> {
    type Target = T;
    #[inline]
    fn deref(&self) -> &T { &self.0 }
}

type Shard<K, V, S> = CachePadded<RwLock<HashMap<K, Arc<V>, S>>>;

pub struct ShardedMap<K, V, S = RandomState> {
    shards: Box<[Shard<K, V, S>]>,
    hash_builder: S,
    shard_mask: usize,
}

impl<K, V> ShardedMap<K, V, RandomState>
where
    K: Hash + Eq,
{
    /// Default shard count scales with CPU parallelism. The 4x multiplier
    /// is a common heuristic: enough shards to make collisions rare, few
    /// enough to keep the per-map memory footprint modest.
    pub fn new() -> Self {
        let cpus = std::thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(4);
        Self::with_shards(cpus * 4)
    }

    pub fn with_shards(shard_count: usize) -> Self {
        Self::with_shards_and_hasher(shard_count, RandomState::new())
    }
}

impl<K, V, S> ShardedMap<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher + Clone,
{
    pub fn with_shards_and_hasher(shard_count: usize, hash_builder: S) -> Self {
        let count = shard_count.max(1).next_power_of_two();
        let shards = (0..count)
            .map(|_| CachePadded(RwLock::new(HashMap::with_hasher(hash_builder.clone()))))
            .collect::<Vec<_>>()
            .into_boxed_slice();

        Self { shards, hash_builder, shard_mask: count - 1 }
    }

    #[inline]
    fn shard_index<Q: Hash + ?Sized>(&self, key: &Q) -> usize {
        let mut hasher = self.hash_builder.build_hasher();
        key.hash(&mut hasher);
        (hasher.finish() as usize) & self.shard_mask
    }

    pub fn insert(&self, key: K, value: V) -> Option<Arc<V>> {
        let idx = self.shard_index(&key);
        self.shards[idx].write().insert(key, Arc::new(value))
    }

    pub fn remove(&self, key: &K) -> Option<Arc<V>> {
        let idx = self.shard_index(key);
        self.shards[idx].write().remove(key)
    }

    /// Cheap read: a single atomic refcount bump while the lock is held,
    /// then the lock is released. Multiple readers of the same hot key
    /// share one allocation instead of each producing a deep clone.
    pub fn get(&self, key: &K) -> Option<Arc<V>> {
        let idx = self.shard_index(key);
        self.shards[idx].read().get(key).cloned()
    }

    pub fn contains_key(&self, key: &K) -> bool {
        let idx = self.shard_index(key);
        self.shards[idx].read().contains_key(key)
    }

    /// Borrow the value under the read lock without bumping the refcount.
    /// Use when the closure is short and you want zero per-call allocation.
    pub fn with<F, R>(&self, key: &K, f: F) -> Option<R>
    where
        F: FnOnce(&V) -> R,
    {
        let idx = self.shard_index(key);
        self.shards[idx].read().get(key).map(|v| f(v.as_ref()))
    }

    /// Copy-on-write update. If the entry has no other Arc references,
    /// mutates in place; otherwise clones and replaces. Requires `V: Clone`.
    pub fn update<F>(&self, key: &K, f: F) -> bool
    where
        V: Clone,
        F: FnOnce(&mut V),
    {
        let idx = self.shard_index(key);
        let mut shard = self.shards[idx].write();
        match shard.get_mut(key) {
            Some(arc) => { f(Arc::make_mut(arc)); true }
            None => false,
        }
    }

    pub fn len(&self) -> usize {
        self.shards.iter().map(|s| s.read().len()).sum()
    }

    pub fn is_empty(&self) -> bool {
        self.shards.iter().all(|s| s.read().is_empty())
    }

    pub fn clear(&self) {
        for shard in self.shards.iter() {
            shard.write().clear();
        }
    }

    pub fn shard_count(&self) -> usize {
        self.shards.len()
    }
}

impl<K, V> Default for ShardedMap<K, V, RandomState>
where
    K: Hash + Eq,
{
    fn default() -> Self { Self::new() }
}
```

